export interface StorageAdapter {
  /** Stores a file under `key` (e.g. "products/<uuid>.webp") and returns its public URL. */
  put(key: string, body: Buffer, contentType: string): Promise<{ url: string }>;
  /** Deletes a file previously returned by put(). Unknown URLs are ignored. */
  delete(url: string): Promise<void>;
}

/** Keys are generated by the app; this guards against anything else reaching the file system. */
export const SAFE_KEY = /^[a-z0-9-]+\/[a-z0-9-]+\.(webp|jpg|png|avif)$/;
